question.solution:
class Node:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def kth_from_end(head, k):
    if k <= 0:
        return None
    fast = head
    for _ in range(k):
        if fast is None:
            return None
        fast = fast.next
    slow = head
    while fast is not None:
        fast = fast.next
        slow = slow.next
    return slow.val

def build(values):
    head = None
    for v in reversed(values):
        head = Node(v, head)
    return head

chain = build([1, 2, 3, 4, 5])
print(kth_from_end(chain, 1))
print(kth_from_end(chain, 5))
print(kth_from_end(chain, 6))
print(kth_from_end(None, 1))
print(kth_from_end(chain, 0))

